{"hypotheses": [
  {
    "name": "Hyp_1",
    "mechanism": "Investment in advertisement and research leads to future growth and profitability, which is often underestimated by the market.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AdExp"},
        {"weight": 0.5, "primitive": "RD"}
      ], 
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "correlation", "primitive": "Beta", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Hyp_2",
    "mechanism": "Profitable firms with large market share may consolidate their position during market downturns, leading to higher returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "GP"},
        {"weight": 1.0, "primitive": "Size"}
      ], 
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "correlation", "primitive": "High52", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.55,
    "expected_decay_half_life_months": null
  },
  {
    "name": "Hyp_3",
    "mechanism": "Firms with low leverage and high liquidity are better equipped to withstand financial distress and thus provide higher returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Leverage"},
        {"weight": -1.0, "primitive": "Illiquidity"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "medium", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "correlation", "primitive": "VolSD", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 60
  },
  {
    "name": "Hyp_4",
    "mechanism": "Firms that invest in organizational capital are likely to have more competitive advantages and hence higher returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": -0.5, "primitive": "AgeIPO"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "Accruals", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.5,
    "expected_decay_half_life_months": 48
  },
  {
    "name": "Hyp_5",
    "mechanism": "Companies with high earnings consistency and low idiosyncratic risk are more stable and may yield higher returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "EarningsConsistency"},
        {"weight": -1.0, "primitive": "IdioVolAHT"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "medium", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "correlation", "primitive": "Beta", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": null
  },
  {
    "name": "Hyp_6",
    "mechanism": "Firms with low bid-ask spread and high analyst optimism are more likely to have information efficiency, leading to higher returns.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "BidAskSpread"},
        {"weight": 1.0, "primitive": "AOP"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "correlation", "primitive": "AnnouncementReturn", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 72
  },
  {
    "name": "Hyp_7",
    "mechanism": "Firms with high cash flows and high sales growth have better financial health and potential for future profitability, leading to higher returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "CF"},
        {"weight": 1.0, "primitive": "GrSaleToGrInv"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "correlation", "primitive": "BM", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": null
  },
  {
    "name": "Hyp_8",
    "mechanism": "Firms with high return on assets and low share issuance may be more efficient and less likely to dilute shareholder value, leading to higher returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "roaq"},
        {"weight": -1.0, "primitive": "ShareIss1Y"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "medium", "direction": "stronger"},
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "correlation", "primitive": "ShareRepurchase", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 60
  }
]}
